Emitter(Box)

Requires(
	vec2 position;
	vec2 velocity;
)

Params(
	@position
	vec2 position;

	@extent(at = position)
	vec2 size;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position = params.position + (vec2(rand(), rand()) - 0.5) * params.size;
	particle.velocity = vec2(0.0);
}

Emitter(Lifetime)

Requires(
	float lifetime;
)

Params(
	@range(min=0, step=0.1)
	float min_lifetime;
	float max_lifetime;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.lifetime = mix(params.min_lifetime, params.max_lifetime, rand());
}

Affector(Wind)

Requires(
	vec2 velocity;
)

Params(
	@vector(scale = 1)
	vec2 velocity;

	@range(min = 0, step = 0.1)
	float drag;

	@range(min = 0, max = 1, step = 0.01)
	float gustiness;
	@range(min = 0, step = 0.1)
	float gust_frequency;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// rand() is reseeded per particle each frame, so this is a stable phase
	float phase = rand() * 6.2831853;
	float gust = sin(ctx.time * params.gust_frequency + phase) * 0.6
						 + sin(ctx.time * params.gust_frequency * 2.33 + phase * 1.7) * 0.4;
	vec2 wind = params.velocity * (1.0 + params.gustiness * gust);
	particle.velocity += (wind - particle.velocity) * min(params.drag * ctx.dt, 1.0);
}

Affector(Flutter)

Requires(
	vec2 velocity;
)

Params(
	@range(min = 0, step = 0.1)
	float strength;

	@range(min = 0, step = 0.1)
	float frequency;

	@range(min = 0, max = 1, step = 0.01)
	float variation;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// rand() is reseeded per particle each frame: stable phase/rate per flake
	float phase = rand() * 6.2831853;
	float freq	= params.frequency * mix(1.0, 0.5 + rand(), params.variation);
	float amp	 = params.strength	* mix(1.0, 0.5 + rand(), params.variation);
	particle.velocity.x += sin(ctx.time * freq + phase) * amp * ctx.dt;
}

Affector(Integrate)

Requires(
	vec2 position;
	vec2 velocity;
)

Params(
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position += particle.velocity * ctx.dt;
}

Renderer(Sprite)

Requires(
	vec2 position;
	float lifetime;
)

Params(
	@range(step=0.1)
	vec2 size;
)

Samplers(
	sampler2D image;
)

#if GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_VERTEX

Varying(2) vec2 v_uv;

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	if (particle.lifetime > 0.0) {
		vec2 corner = quad();
		// The atlas is y-down while the quad is y-up
		v_uv = vec2(corner.x + 0.5, 0.5 - corner.y);
		gl_Position = grain_transform * vec4(particle.position + corner * params.size, 0.0, 1.0);
	} else {
		cull();
	}
}

#elif GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_FRAGMENT

Varying(2) vec2 v_uv;

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// The atlas is premultiplied, so fading scales the whole color
	grain_Color = texture(image, atlas_uv(image_uvrect, v_uv))
		* clamp(particle.lifetime, 0.0, 1.0);
}

#endif
